// Bounded subset validator for schemas generated by exact installed Codex0.128.0.
// Test-only, no network/ref retrieval. Unsupported keywords must not be silently
// treated as validated; these fixtures use type/required/enum/local refs/combinators.
use serde_json::Value;
pub fn request(v: &Value) {
    let source = match v["method"].as_str().unwrap_or("") {
        "model/list" => include_str!("ModelListParams.json"),
        "initialize" => include_str!("InitializeParams.json"),
        "account/login/start" => include_str!("LoginAccountParams.json"),
        "account/login/cancel" => include_str!("CancelLoginAccountParams.json"),
        "account/read" => include_str!("GetAccountParams.json"),
        "thread/start" => include_str!("ThreadStartParams.json"),
        "turn/start" => include_str!("TurnStartParams.json"),
        "turn/interrupt" => include_str!("TurnInterruptParams.json"),
        "initialized" | "account/logout" => {
            assert!(v.get("params").is_none());
            return;
        }
        // Approval replies are checked separately by their fixture mode.
        "" => return,
        _ => panic!("unmapped outgoing method"),
    };
    let root: Value = serde_json::from_str(source).unwrap();
    assert!(
        valid(&root, &v["params"], &root),
        "request rejected by pinned official schema: {}",
        v["method"]
    );
}
pub fn valid(s: &Value, v: &Value, root: &Value) -> bool {
    if let Some(b) = s.as_bool() {
        return b;
    }
    if let Some(r) = s["$ref"].as_str() {
        return r.starts_with('#') && root.pointer(&r[1..]).is_some_and(|s| valid(s, v, root));
    }
    if let Some(a) = s["allOf"].as_array() {
        if !a.iter().all(|x| valid(x, v, root)) {
            return false;
        }
    }
    if let Some(a) = s["anyOf"].as_array() {
        if !a.iter().any(|x| valid(x, v, root)) {
            return false;
        }
    }
    if let Some(a) = s["oneOf"].as_array() {
        if a.iter().filter(|x| valid(x, v, root)).count() != 1 {
            return false;
        }
    }
    if let Some(a) = s["enum"].as_array() {
        if !a.contains(v) {
            return false;
        }
    }
    let fits = |t: &str| match t {
        "string" => v.is_string(),
        "object" => v.is_object(),
        "array" => v.is_array(),
        "boolean" => v.is_boolean(),
        "null" => v.is_null(),
        "integer" => v.is_i64() || v.is_u64(),
        "number" => v.is_number(),
        _ => false,
    };
    if let Some(t) = s["type"].as_str() {
        if !fits(t) {
            return false;
        }
    }
    if let Some(ts) = s["type"].as_array() {
        if !ts.iter().any(|t| t.as_str().is_some_and(fits)) {
            return false;
        }
    }
    if let Some(min) = s["minimum"].as_f64() {
        if v.as_f64().is_some_and(|x| x < min) {
            return false;
        }
    }
    if let Some(o) = v.as_object() {
        if let Some(req) = s["required"].as_array() {
            if !req.iter().all(|k| o.contains_key(k.as_str().unwrap())) {
                return false;
            }
        }
        for (key, value) in o {
            if let Some(prop) = s.get("properties").and_then(|p| p.get(key)) {
                if !valid(prop, value, root) {
                    return false;
                }
            } else if s.get("additionalProperties") == Some(&Value::Bool(false)) {
                return false;
            }
        }
    }
    if let Some(a) = v.as_array() {
        if let Some(items) = s.get("items") {
            if !a.iter().all(|v| valid(items, v, root)) {
                return false;
            }
        }
    }
    true
}

pub fn desktop_request(v: &Value) {
    if v["method"] == "turn/start" {
        let root: Value =
            serde_json::from_str(include_str!("DesktopTurnStartParams.json")).unwrap();
        assert!(
            valid(&root, &v["params"], &root),
            "request rejected by installed official 0.159.2 schema"
        );
    } else {
        request(v);
    }
}
